import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// One app in the factory. Loaded from assets/apps.json (generated by
/// tool/factory.py from `apps/<id>.json`).
class AppConfig {
  AppConfig({
    required this.id,
    required this.bank,
    required this.locales,
    required this.title,
    required this.color,
    required this.examQuestions,
    required this.examMinutes,
    required this.passPercent,
    required this.freeRatio,
    required this.premiumProductId,
    required this.adsEnabled,
    required this.bannerAdUnit,
    required this.interstitialAdUnit,
    required this.privacyPolicyUrl,
    required this.supportEmail,
    required this.examBodies,
    this.officialSources = const [],
  });

  final String id;
  final String bank;

  /// First entry is the primary language (UI + questions). The second, if any,
  /// is the helper language shown by the bilingual toggle.
  final List<String> locales;
  final Map<String, String> title;
  final Color color;
  final int examQuestions;
  final int examMinutes;
  final int passPercent;
  final double freeRatio;
  final String premiumProductId;

  /// False: no ads at all, free users are upsold to premium instead.
  final bool adsEnabled;
  final String bannerAdUnit;
  final String interstitialAdUnit;
  final String privacyPolicyUrl;
  final String supportEmail;

  /// Organizations named in the "not affiliated with" disclaimer, per UI
  /// language.
  final Map<String, String> examBodies;

  /// Government pages the questions are based on (label, url). Shown on the
  /// home screen and in Settings (Play: Misleading Claims policy).
  final List<(String, String)> officialSources;

  String examBodiesFor(String lang) =>
      examBodies[lang] ?? examBodies['en'] ?? 'any exam provider';

  String get primary => locales.first;
  String? get secondary => locales.length > 1 ? locales[1] : null;

  String titleFor(String lang) => title[lang] ?? title.values.first;

  factory AppConfig.fromJson(Map<String, dynamic> j) {
    final exam = j['exam'] as Map<String, dynamic>;
    final admob = j['admob'] as Map<String, dynamic>;
    return AppConfig(
      id: j['id'] as String,
      bank: j['bank'] as String,
      locales: List<String>.from(j['locales'] as List),
      title: Map<String, String>.from(j['title'] as Map),
      color: Color(
        int.parse((j['color'] as String).substring(1), radix: 16) | 0xFF000000,
      ),
      examQuestions: exam['questions'] as int,
      examMinutes: exam['minutes'] as int,
      passPercent: exam['passPercent'] as int,
      freeRatio: (j['freeRatio'] as num).toDouble(),
      premiumProductId: j['premiumProductId'] as String,
      adsEnabled: j['ads'] as bool? ?? true,
      bannerAdUnit: admob['banner'] as String,
      interstitialAdUnit: admob['interstitial'] as String,
      privacyPolicyUrl: j['privacyPolicyUrl'] as String,
      supportEmail: j['supportEmail'] as String,
      examBodies: Map<String, String>.from(j['examBodies'] as Map? ?? {}),
      officialSources: [
        for (final e in j['officialSources'] as List? ?? const [])
          (e['label'] as String, e['url'] as String),
      ],
    );
  }

  /// Which app this binary is: `--dart-define=APP_ID=x` wins (web/tests),
  /// otherwise the Android flavor, otherwise the first app.
  static Future<AppConfig> load() async {
    final all = jsonDecode(
      await rootBundle.loadString('assets/apps.json'),
    ) as Map<String, dynamic>;
    const fromDefine = String.fromEnvironment('APP_ID');
    // Web builds (store screenshots) can switch app with ?app=<id>.
    final fromUrl = kIsWeb ? Uri.base.queryParameters['app'] : null;
    final id = fromUrl != null && all.containsKey(fromUrl)
        ? fromUrl
        : fromDefine.isNotEmpty
        ? fromDefine
        : (appFlavor != null && all.containsKey(appFlavor))
        ? appFlavor!
        : all.keys.first;
    return AppConfig.fromJson(all[id] as Map<String, dynamic>);
  }
}

class QText {
  QText(this.question, this.options, this.explanation);
  final String question;
  final List<String> options;
  final String explanation;
}

class Question {
  Question(this.id, this.category, this.answer, this.texts);
  final String id;
  final String category;
  final int answer;
  final Map<String, QText> texts;

  QText text(String lang) => texts[lang] ?? texts['en'] ?? texts.values.first;
  bool hasLang(String lang) => texts.containsKey(lang);
}

class Category {
  Category(this.id, this.names);
  final String id;
  final Map<String, String> names;
  String name(String lang) => names[lang] ?? names['en'] ?? id;
}

class Bank {
  Bank(this.id, this.version, this.categories, this.questions);

  final String id;
  final String version;
  final List<Category> categories;
  final List<Question> questions;

  late final Map<String, Question> byId = {for (final q in questions) q.id: q};

  List<Question> inCategory(String cat) =>
      questions.where((q) => q.category == cat).toList();

  /// The free tier is the first [ratio] of every category, so free users get a
  /// taste of every topic.
  Set<String> freeIds(double ratio) {
    final ids = <String>{};
    for (final c in categories) {
      final qs = inCategory(c.id);
      final n = (qs.length * ratio).ceil().clamp(1, qs.length);
      ids.addAll(qs.take(n).map((q) => q.id));
    }
    return ids;
  }

  factory Bank.fromJson(Map<String, dynamic> j) {
    final cats = [
      for (final c in j['categories'] as List)
        Category(c['id'] as String, Map<String, String>.from(c['name'] as Map)),
    ];
    final qs = [
      for (final q in j['questions'] as List)
        Question(q['id'] as String, q['cat'] as String, q['a'] as int, {
          for (final e in (q['t'] as Map<String, dynamic>).entries)
            e.key: QText(
              e.value['q'] as String,
              List<String>.from(e.value['o'] as List),
              e.value['e'] as String,
            ),
        }),
    ];
    return Bank(j['id'] as String, j['version'] as String, cats, qs);
  }

  static Future<Bank> load(String id) async => Bank.fromJson(
    jsonDecode(await rootBundle.loadString('assets/banks/$id.json'))
        as Map<String, dynamic>,
  );
}
